/** 当前 markup 可见分组里，由组合属性统一管理的子 attr 键集合 */
export function getCompositeManagedKeys(groups = []) {
  const keys = new Set();
  for (const group of groups) {
    for (const option of group.options) {
      if (option.virtual && Array.isArray(option.applyKeys)) {
        option.applyKeys.forEach((key) => keys.add(key));
      }
    }
  }
  return keys;
}

export function AttrGroupToObj() {
  let result = {};
  for (let group of CnLabelGroup) {
    for (let option of group.options) {
      result[option.attr] = option;
    }
  }
  return result;
}

