import {
  DEFAULT_ANGLE_MULTIPLE,
  getPathAnchorAfterSource,
  getPathAnchorBeforeIndex,
  getPathAnchorBeforeTarget,
  pointsNearlyEqual,
  snapPointByAngleMultiple,
  toPointLike
} from '../util/EdgeSnapUtil';

let disposeFn = null;
let shiftKeyDown = false;
let isApplyingSnap = false;

function onKeyDown(e) {
  if (e.key === 'Shift') {
    shiftKeyDown = true;
  }
}

function onKeyUp(e) {
  if (e.key === 'Shift') {
    shiftKeyDown = false;
  }
}

function canSnapEdge(edge) {
  if (!edge?.isEdge?.()) {
    return false;
  }
  if (edge.prop('lock') || edge.prop('group-lock')) {
    return false;
  }
  return true;
}

function findSingleChangedVertexIndex(previous, current) {
  const prev = previous || [];
  const curr = current || [];
  const maxLen = Math.max(prev.length, curr.length);
  let changedIndex = -1;
  for (let i = 0; i < maxLen; i += 1) {
    const p = prev[i];
    const c = curr[i];
    if (!c) {
      continue;
    }
    if (!p || p.x !== c.x || p.y !== c.y) {
      if (changedIndex >= 0) {
        return -1;
      }
      changedIndex = i;
    }
  }
  return changedIndex;
}

function applySnappedPoint(setter, point, options) {
  isApplyingSnap = true;
  try {
    setter(point, options);
  } finally {
    isApplyingSnap = false;
  }
}

/**
 * 编辑线条时按住 Shift，按与 DrawEdge 相同的 10° 步进吸附端点/路径点
 */
export function initEdgeShiftSnap(graph, { isEnabled = () => true } = {}) {
  disposeEdgeShiftSnap();
  shiftKeyDown = false;
  isApplyingSnap = false;

  const shouldSnap = (edge, options) =>
    !isApplyingSnap &&
    shiftKeyDown &&
    options?.ui &&
    isEnabled() &&
    canSnapEdge(edge);

  const onChangeSource = ({ edge, current, options }) => {
    if (!shouldSnap(edge, options) || edge.getSourceCellId?.()) {
      return;
    }
    const point = toPointLike(edge.getSourcePoint());
    const anchor = getPathAnchorAfterSource(edge);
    if (!point || !anchor) {
      return;
    }
    const snapped = snapPointByAngleMultiple(
      point,
      anchor,
      DEFAULT_ANGLE_MULTIPLE
    );
    if (pointsNearlyEqual(point, snapped)) {
      return;
    }
    applySnappedPoint(
      (p, opts) => {
        if (current && typeof current === 'object' && current.cell) {
          return;
        }
        edge.setSource({ ...(current || {}), ...p }, opts);
      },
      snapped,
      { ui: true, toolId: options?.toolId }
    );
  };

  const onChangeTarget = ({ edge, current, options }) => {
    if (!shouldSnap(edge, options) || edge.getTargetCellId?.()) {
      return;
    }
    const point = toPointLike(edge.getTargetPoint());
    const anchor = getPathAnchorBeforeTarget(edge);
    if (!point || !anchor) {
      return;
    }
    const snapped = snapPointByAngleMultiple(
      point,
      anchor,
      DEFAULT_ANGLE_MULTIPLE
    );
    if (pointsNearlyEqual(point, snapped)) {
      return;
    }
    applySnappedPoint(
      (p, opts) => {
        if (current && typeof current === 'object' && current.cell) {
          return;
        }
        edge.setTarget({ ...(current || {}), ...p }, opts);
      },
      snapped,
      { ui: true, toolId: options?.toolId }
    );
  };

  const onChangeVertices = ({ edge, current, previous, options }) => {
    if (!shouldSnap(edge, options)) {
      return;
    }
    const index = findSingleChangedVertexIndex(previous, current);
    if (index < 0) {
      return;
    }
    const point = toPointLike(current[index]);
    const anchor = getPathAnchorBeforeIndex(edge, index);
    if (!point || !anchor) {
      return;
    }
    const snapped = snapPointByAngleMultiple(
      point,
      anchor,
      DEFAULT_ANGLE_MULTIPLE
    );
    if (pointsNearlyEqual(point, snapped)) {
      return;
    }
    applySnappedPoint(
      (p, opts) => edge.setVertexAt(index, p, opts),
      snapped,
      { ui: true, toolId: options?.toolId }
    );
  };

  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  graph.on('edge:change:source', onChangeSource);
  graph.on('edge:change:target', onChangeTarget);
  graph.on('edge:change:vertices', onChangeVertices);

  disposeFn = () => {
    window.removeEventListener('keydown', onKeyDown);
    window.removeEventListener('keyup', onKeyUp);
    graph.off('edge:change:source', onChangeSource);
    graph.off('edge:change:target', onChangeTarget);
    graph.off('edge:change:vertices', onChangeVertices);
    disposeFn = null;
    shiftKeyDown = false;
    isApplyingSnap = false;
  };
}

export function disposeEdgeShiftSnap() {
  if (disposeFn) {
    disposeFn();
  }
}
