// import { importAll } from '../util/Utils';
import { register } from '@antv/x6-vue-shape';
import { Theme } from '../components/charts/Theme';
import { merge } from 'lodash';
import {
  NODE_TYPE_NAME,
  NODE_TYPES,
  ECHARTS_DEFAULT_CONFIG_KEY
} from '../constants/Constants';
import {
  CHARTS_GROUP_KEY,
  getChartDefinitionKey,
  registerChartShapeKeys
} from '../util/DefinitionKeyUtil.js';
let theme = new Theme();
let chartsKeys = [];
export const initChartsNode = (graph) => {
  let result = [];
  chartsKeys.forEach((key) => {
    const definitionKey = getChartDefinitionKey(key) ?? key;
    result.push(
      graph.createNode({
        key: definitionKey,
        groupKey: CHARTS_GROUP_KEY,
        shape: definitionKey,
        label: definitionKey,
        width: 400,
        height: 300,
        attrs: {
          foreignObject: {
            style: {
              transform: 'scale(0.3)'
            }
          }
        }
      })
    );
  });

  return result;
};
export const registerChart = () => {
  let r = require.context('../components/charts', false, /\.vue$/);
  let __modules = {};
  r.keys().forEach((key) => {
    let m = r(key).default;
    let n = m.name;
    __modules[n] = m;
  });
  let charts = __modules;
  let localChartsKeys = [];
  for (let [key, component] of Object.entries(charts)) {
    // let chartsConfig = component.data()[ECHARTS_DEFAULT_CONFIG_KEY];
    let chartsConfig;
    if (component.mixins) {
      for (let mixins of component.mixins) {
        chartsConfig = mixins.data()[ECHARTS_DEFAULT_CONFIG_KEY];
        if (chartsConfig) {
          break;
        }
      }
    } else {
      chartsConfig = component.data()[ECHARTS_DEFAULT_CONFIG_KEY];
    }
    if (chartsConfig?.theme) {
      let themeJson = theme.getTheme(chartsConfig.theme);
      merge(chartsConfig, themeJson);
    }
    register({
      shape: key,
      label: key,
      width: 100,
      height: 100,
      component: component,
      charts: chartsConfig,
      [NODE_TYPE_NAME]: NODE_TYPES.echarts,
      visible: true
    });
    localChartsKeys.push(key);
  }
  chartsKeys = localChartsKeys;
  registerChartShapeKeys(localChartsKeys);
};
