import { merge, cloneDeep } from 'lodash';
import { TOUCH_OFFS } from '../constants/Constants';
import Animation from './offects/Animation';
import Data from './offects/Data';
import Status from './offects/Status';
import Style from './offects/Style';
import Text from './offects/Text';
import Original from './offects/Original';
import Progress from './offects/Progress';
import Transition from './offects/Transition';
import GDAnimation from './offects/GDAnimation';

export class Offect {
  constructor(graph, audio) {
    this.graph = graph;
    this.cells = {};
    this.data = new Data();
    this.animation = new Animation();
    this.status = new Status();
    this.style = new Style();
    this.text = new Text();
    this.progress = new Progress();
    this.original = new Original();
    this.transition = new Transition();
    this.gdAnimation = new GDAnimation();
    this.audio = audio;
  }
  clear() {
    this.cells = {};
  }
  editViewChangeData(cell, isEditView, formulas) {
    let cellConfig;
    if (formulas) {
      cellConfig = this.packageCellConfig(formulas, cell);

      let localCellConfig = this.cells[cell.id];
      if (localCellConfig) {
        cellConfig.orgCell = localCellConfig.orgCell;
      }
    }
    this.changeData(cell, {}, isEditView, cellConfig);
  }
  //改变数据
  changeData(cell, data, isEditView, cellConfigP) {
    console.log('offect 数据改变');
    let cellConfig = cellConfigP ?? this.cells[cell.id];
    if (!cellConfig) {
      let formulas = cell.getProp('formulas');
      cellConfig = this.packageCellConfig(formulas, cell);
      this.cells[cell.id] = cellConfig;
    }
    if (!cellConfig) {
      return;
    }
    //属性深度合并
    merge(cellConfig.data, data);

    //执行数据处理显示
    // if (cellConfig.type == FORMULAS.data.value) {
    this.data.execute(cellConfig);
    // return;
    // }
    //执行公式计算效果显示
    // if (cellConfig.type == FORMULAS.complex.value && cellConfig.ifs) {
    // for (let [key, value] of Object.entries(cellConfig.ifs)) {
    // if (executeIfIndex == undefined) {
    if (!cellConfig?.ifs?.length) {
      return;
    }
    for (let index = 0; index < cellConfig.ifs.length; index++) {
      let value = cellConfig.ifs[index];
      let result = isEditView;
      if (isEditView === undefined) {
        //正式运行时计算真实结果
        let ifc = this.calcIf(value, cellConfig.data);
        if (ifc.indexOf('{') != -1) {
          result = null;
        } else {
          try {
            result = eval(ifc);
          } catch (error) {
            //执行告警
          }
        }
      }
      value.result = result;
    }
    //永远让计算结果为false的在最前面执行，否则有可能覆盖为true的效果
    cellConfig.ifs.sort((a, b) => {
      if (a.result && b.result) {
        return 0;
      }
      if (!a.result && b.result) {
        return -1;
      }
      if (a.result && !b.result) {
        return 1;
      }
    });
    if (this.graph) {
      this.graph.startBatch(cellConfig.cell.id);
    }
    cellConfig.ifs.forEach((item) => {
      if (item.result != null) {
        this.execute(cellConfig, item, item.result, isEditView);
      }
    });
    if (this.graph) {
      this.graph.stopBatch(cellConfig.cell.id);
    }
    /* } else {
        this.execute(cellConfig, cellConfig.ifs[executeIfIndex], isEditView);
      } */
    // }
  }
  execute(cellConfig, value, result, isEditView) {
    value.touchOff.type.forEach((type) => {
      switch (type) {
        case TOUCH_OFFS.style.value:
          this.style.execute(cellConfig, value, result);
          break;
        case TOUCH_OFFS.status.value:
          this.status.execute(cellConfig, value, result);

          break;
        case TOUCH_OFFS.animation.value:
          this.animation.execute(cellConfig, value, result);
          break;
        case TOUCH_OFFS.progress.value:
          this.progress.execute(cellConfig, value, result);
          break;
        case TOUCH_OFFS.text.value:
          if (isEditView === undefined) {
            this.text.execute(cellConfig, value, result);
          }
          break;
        case TOUCH_OFFS.transition.value:
          // if (isEditView === undefined) {
          this.transition.execute(cellConfig, value, result, isEditView);
          // }
          break;
        case TOUCH_OFFS.gdanimation.value:
          // if (isEditView === undefined) {
          this.gdAnimation.execute(cellConfig, value, result);
          // }
          break;
        default:
          break;
      }
    });
  }
  packageCellConfig(formulas, cell) {
    if (!formulas) return;

    let points = [];
    // 公式类型
    let ifs;
    // if (formulas.type == FORMULAS.complex.value && formulas.cases) {
    if (formulas.cases) {
      ifs = [];
      formulas.cases.forEach((item) => {
        item?.points?.forEach((point) => {
          item.ifstr = item.ifstr.replaceAll(
            `{${point.mpKey}.${point.attrKey}}`,
            `{${point.mpId}.${point.attrId}}`
          );
        });
        ifs.push(item);
        points.push(...item.points);
      });
    }
    // 显示数据类型
    let format;
    if (
      formulas?.format?.point &&
      formulas?.format?.point?.mpId !== undefined &&
      formulas?.format?.point?.mpId !== ''
    ) {
      format = formulas.format;
      points.push(format.point);
    }
    return {
      cell: cell,
      graph: this.graph,
      type: formulas.type, //配置类型，数据|公式
      points,
      ifs, //公式条件
      format, //数据格式化
      data: {}, //存放所有用到的数据
      orgCell: cloneDeep(cell.store.data)
    };
  }
  calcIf(caseObj, data) {
    let ifstr = caseObj.ifstr;
    for (let [key, value] of Object.entries(data)) {
      ifstr = ifstr.replaceAll(`{${key}}`, value.value);
    }
    return ifstr;
  }
}
