import { EDGE_ANGLE_SNAP_DEGREES } from '../config/SystemConfig.js';

/** 画线角度吸附步进（度），与 SystemConfig.EDGE_ANGLE_SNAP_DEGREES 一致 */
export const DEFAULT_ANGLE_MULTIPLE = EDGE_ANGLE_SNAP_DEGREES;

/**
 * 将 point 相对 anchor 按 angleMultiple 步进吸附（保持到 anchor 的距离不变）
 */
export function snapPointByAngleMultiple(
  point,
  anchor,
  angleMultiple = EDGE_ANGLE_SNAP_DEGREES
) {
  const dx = point.x - anchor.x;
  const dy = point.y - anchor.y;
  const radius = Math.sqrt(dx * dx + dy * dy);
  if (radius === 0) {
    return { x: point.x, y: point.y };
  }
  const angleInDegrees = Math.atan2(dy, dx) * (180 / Math.PI);
  const roundedAngle =
    Math.round(angleInDegrees / angleMultiple) * angleMultiple;
  const angleInRadians = (roundedAngle * Math.PI) / 180;
  return {
    x: anchor.x + Math.cos(angleInRadians) * radius,
    y: anchor.y + Math.sin(angleInRadians) * radius
  };
}

export function pointsNearlyEqual(a, b, eps = 0.01) {
  return Math.abs(a.x - b.x) < eps && Math.abs(a.y - b.y) < eps;
}

export function toPointLike(p) {
  if (p == null || p.x == null || p.y == null) {
    return null;
  }
  return { x: p.x, y: p.y };
}

/** 路径上 index 前一个锚点（与 DrawEdge 绘制 target 时的逻辑一致） */
export function getPathAnchorBeforeIndex(edge, index) {
  const vertices = edge.getVertices() || [];
  if (index > 0) {
    return toPointLike(vertices[index - 1]);
  }
  return toPointLike(edge.getSourcePoint());
}

/** 拖拽 source 端点时，路径上的下一个参考点 */
export function getPathAnchorAfterSource(edge) {
  const vertices = edge.getVertices() || [];
  if (vertices.length > 0) {
    return toPointLike(vertices[0]);
  }
  return toPointLike(edge.getTargetPoint());
}

/** 拖拽 target 端点时，路径上的上一个参考点 */
export function getPathAnchorBeforeTarget(edge) {
  const vertices = edge.getVertices() || [];
  if (vertices.length > 0) {
    return toPointLike(vertices[vertices.length - 1]);
  }
  return toPointLike(edge.getSourcePoint());
}
