export const insertAlarmPoint = function (graph) {
  let cell = graph.getCellById(ALARM_NODE_ID);
  if (!cell) {
    graph.addNodes([
      {
        id: ALARM_NODE_ID,
        shape: 'super-node',
        visible: false,
        width: 1,
        height: 1,
        x: 0,
        y: 0,
        markup: [
          {
            tagName: 'rect'
          }
        ],
        lock: true
      }
    ]);
  }
};
export const reInsertPoint = function (graph, pageSize) {
  graph.removeCells([
    POINT_LEFT_TOP,
    POINT_RIGHT_TOP,
    POINT_LEFT_BOTTOM,
    POINT_BOTTOM_BOTTOM
  ]);
  graph.addNodes([
    {
      id: POINT_LEFT_TOP,
      shape: 'rect',
      visible: false,
      width: 1,
      height: 1,
      x: 0,
      y: 0,
      lock: true
    },
    {
      id: POINT_RIGHT_TOP,
      shape: 'rect',
      visible: false,
      width: 1,
      height: 1,
      x: pageSize.width - 1,
      y: 0,
      lock: true
    },
    {
      id: POINT_LEFT_BOTTOM,
      shape: 'rect',
      visible: false,
      width: 1,
      height: 1,
      x: 0,
      y: pageSize.height - 1,
      lock: true
    },
    {
      id: POINT_BOTTOM_BOTTOM,
      shape: 'rect',
      visible: false,
      width: 1,
      height: 1,
      x: pageSize.width - 1,
      y: pageSize.height - 1,
      lock: true
    }
  ]);
};
/* 修改画布大小并适应屏幕 */
export const changePageSize = function (graph, pageSize) {
  // let graphArea = graph.getGraphArea();
  let scroller = graph.getPlugin('scroller');
  if (scroller) {
    graph.zoom(1, { absolute: true });
    graph.options.width = pageSize.width;
    graph.options.height = pageSize.height;
    scroller.resizePage(pageSize.width, pageSize.height);
    graph.zoom(1, { absolute: true });
    scroller.transitionToRect(
      {
        x: 0,
        y: 0,
        ...pageSize
      },
      {
        scaleGrid: 0.05,
        visibility: 1 // 矩形覆盖 90% 视口区域
        // maxScale: 3 // 画布最大缩放比例为 3
      }
    );
    reInsertPoint(graph, pageSize);
  }
  console.log('执行了画布大小');
};
export const mattAlign = function (graph) {
  let cells = graph.getSelectedCells();
  if (cells.length < 1) {
    return;
  }

  let yObjs = groupBy(cells, (cell) => {
    if (cell.isEdge()) {
      return null;
    }
    let { y } = cell.position();
    return y;
  });
  let minY;
  let minX;
  let nextNodeStartX = [];
  let nextNodeStartY = [];
  let colCount = 1;
  graph.startBatch('mattAlign');
  for (let [key, values] of Object.entries(yObjs)) {
    if (key === null) {
      continue;
    }
    values.sort((a, b) => {
      let ap = a.position?.();
      let bp = b.position?.();
      return ap.x - bp.x;
    });
    values.forEach((cell) => {
      let { x, y } = cell.position();
      let { width, height } = cell.size();
      if (colCount === 1) {
        if (minY === undefined) {
          minY = minY ?? y;
          minX = minX ?? x;
        }
        if (nextNodeStartY.length === 0) {
          nextNodeStartX[0] = x + width;
          nextNodeStartY[0] = y + height;
          cell.position(x, y);
        } else {
          cell.position(minX, nextNodeStartY[0]);
          let { x, y } = cell.position();
          let { width, height } = cell.size();
          nextNodeStartX[0] = x + width;
          nextNodeStartY[0] = y + height;
        }
      }
      if (colCount === 2) {
        if (nextNodeStartY.length < 2) {
          cell.position(nextNodeStartX[0], minY);
          let { y } = cell.position();
          let { height } = cell.size();
          nextNodeStartY[1] = y + height;
        } else {
          cell.position(nextNodeStartX[0], nextNodeStartY[1]);
          let { y } = cell.position();
          let { height } = cell.size();
          nextNodeStartY[1] = y + height;
        }
        colCount = 0;
      }
      colCount++;
    });
  }
  graph.stopBatch('mattAlign');
};
export const pageTopAlign = function (graph) {
  let cells = graph.getSelectedCells();
  if (cells.length < 1) {
    return;
  }
  let minYNode = minBy(cells, (cell) => {
    if (cell.isEdge()) {
      return null;
    }
    return cell.position().y;
  });
  if (minYNode === undefined) {
    return;
  }
  let minY = minYNode.position().y;
  graph.startBatch('pageTopAlign');
  cells.forEach((cell) => {
    if (cell.isEdge()) {
      let vertices = cell.getVertices();
      vertices?.forEach(({ x, y }, index) => {
        cell.setVertexAt(index, { x: x, y: y - minY });
      });
      if (!cell.getSourceCellId()) {
        let { x, y } = cell.getSourcePoint();
        cell.setSource({
          x: x,
          y: y - minY
        });
      }
      if (!cell.getTargetCellId()) {
        let { x, y } = cell.getTargetPoint();
        cell.setTarget({
          x: x,
          y: y - minY
        });
      }
      return;
    }
    let { x, y } = cell.position();
    cell.position(x, y - minY, {
      deep: true
    });
  });
  graph.stopBatch('pageTopAlign');
};
