export const pagePVCenterAlign = function (graph, graphConfig) {
  let cells = graph.getSelectedCells();
  if (cells.length < 1) {
    return;
  }
  let minY, maxY;
  cells.forEach((cell) => {
    if (cell.isEdge()) {
      return;
    }
    let { y } = cell.position();
    let { height } = cell.size();
    let yHeight = y + height;
    minY = minY ?? y;
    maxY = maxY ?? y;
    minY > y && (minY = y);
    maxY < yHeight && (maxY = yHeight);
  });
  if (maxY === undefined || minY === undefined) {
    return;
  }
  let center = minY + (maxY - minY) / 2;
  let pageHeight = graphConfig.pageSize.height;
  let move = pageHeight / 2 - center;
  graph.startBatch('pagePVCenterAlign');
  cells.forEach((cell) => {
    if (cell.isEdge()) {
      let vertices = cell.getVertices();
      vertices?.forEach(({ x, y }, index) => {
        cell.setVertexAt(index, { x: x, y: y + move });
      });
      if (!cell.getSourceCellId()) {
        let { x, y } = cell.getSourcePoint();
        cell.setSource({
          x: x,
          y: y + move
        });
      }
      if (!cell.getTargetCellId()) {
        let { x, y } = cell.getTargetPoint();
        cell.setTarget({
          x: x,
          y: y + move
        });
      }
      return;
    }
    let { x, y } = cell.position();
    cell.position(x, y + move, {
      deep: true
    });
  });
  graph.stopBatch('pagePVCenterAlign');
};
