export const getEdgePoints = function (cell, key) {
  let vertices = cell.getVertices();
  let sourcePoint = cell.getSourcePoint();
  let targetPoint = cell.getTargetPoint();
  let result = [...vertices, sourcePoint, targetPoint];
  if (key) {
    return result.map((point) => point[key]);
  }
  return result;
};
