/* 水平并列排列 */
export const hjAlign = function (graph) {
  let cells = graph.getSelectedCells();
  if (cells.length <= 1) {
    return;
  }
  const { nodes, edges } = partitionAlignCells(cells);
  graph.startBatch('hjAlign');
  if (nodes.length > 1) {
    const sorted = nodes.sort((a, b) => a.position().x - b.position().x);
    let preXWidth;
    sorted.forEach((cell) => {
      if (preXWidth != undefined) {
        let { y } = cell.position();
        cell.position(preXWidth, y, {
          deep: true
        });
      }
      let { x } = cell.position();
      let { width } = cell.size();
      preXWidth = x + width;
    });
  }
  if (edges.length > 1) {
    EdgeAlign.edgeHjAlign(edges);
  }
  graph.stopBatch('hjAlign');
};
