export const hjAverageAlign = function (graph) {
  let cells = graph.getSelectedCells();
  if (cells.length <= 1) {
    return;
  }
  const { nodes, edges } = partitionAlignCells(cells);
  graph.startBatch('hjAverageAlign');
  if (nodes.length > 1) {
    const sorted = nodes.sort((a, b) => a.position().x - b.position().x);
    let nodeSumWidth = 0;
    let minX;
    let maxXWidth;
    sorted.forEach((cell) => {
      let { x } = cell.position();
      let { width } = cell.size();
      minX = minX ?? x;
      maxXWidth = maxXWidth ?? x;
      maxXWidth = maxXWidth < x + width ? x + width : maxXWidth;
      nodeSumWidth += width;
    });
    if (maxXWidth != null && minX != null) {
      const blankWidth = maxXWidth - minX - nodeSumWidth;
      if (blankWidth > 0) {
        const averBlankWidth = blankWidth / (sorted.length - 1);
        let preXWidth;
        sorted.forEach((cell) => {
          let { x, y } = cell.position();
          let { width } = cell.size();
          if (!preXWidth) {
            preXWidth = x + width;
            return;
          }
          cell.position(preXWidth + averBlankWidth, y, {
            deep: true
          });
          preXWidth = preXWidth + averBlankWidth + width;
        });
      }
    }
  }
  if (edges.length > 1) {
    EdgeAlign.edgeHjAverageAlign(edges);
  }
  graph.stopBatch('hjAverageAlign');
};
