export const centerAlign = function (graph) {
  let cells = graph.getSelectedCells();
  if (cells.length <= 1) {
    return;
  }
  const { nodes, edges } = partitionAlignCells(cells);
  graph.startBatch('centerAlign');
  if (nodes.length > 1) {
    let minX;
    let maxX;
    nodes.forEach((cell) => {
      let { x } = cell.position();
      let { width } = cell.size();
      let xWidth = x + width;
      minX = minX ?? x;
      maxX = maxX ?? xWidth;
      minX > x && (minX = x);
      maxX < xWidth && (maxX = xWidth);
    });
    const center = maxX - (maxX - minX) / 2;
    nodes.forEach((cell) => {
      let { x, y } = cell.position();
      let { width } = cell.size();
      x -= x + width / 2 - center;
      cell.position(x, y, {
        deep: true
      });
    });
  }
  if (edges.length > 1) {
    EdgeAlign.edgeCenterAlign(edges);
  }
  graph.stopBatch('centerAlign');
};
