export const toFront = function (graph, selectCells) {
  if (!selectCells) {
    selectCells = graph.getSelectedCells();
  }

  selectCells = selectCells.sort((a, b) => {
    return a.zIndex - b.zIndex;
  });
  graph.startBatch('toFront');
  selectCells.forEach((cell) => {
    cell.toFront();
  });
  graph.stopBatch('toFront');
};

/** 粘贴组合后把父节点置顶层，与菜单「组合」一致，避免子图元盖住父节点导致边缘无法拖拽 */
export const fixGroupParentsZIndexAfterPaste = (graph, cells) => {
  const parents = (cells || []).filter(
    (cell) => cell?.isNode?.() && cell.shape === 'custom-group-node'
  );
  if (parents.length) {
    toFront(graph, parents);
  }
};

export const toBack = function (graph, selectCells) {
  if (!selectCells) {
    selectCells = graph.getSelectedCells();
  }
  selectCells = selectCells.sort((a, b) => {
    return b.zIndex - a.zIndex;
  });
  graph.startBatch('toBack');
  selectCells.forEach((cell) => {
    cell.toBack();
  });
  graph.stopBatch('toBack');
};
export const moveUp = function (graph) {
  let selectCells = graph.getSelectedCells();
  graph.startBatch('moveUp');
  selectCells.forEach((cell) => {
    let topMinZIndex = cell.model.getMaxZIndex();
    let selectNodeZIndex = cell.zIndex;
    let topMinNodes = cell.model.getCells().filter((item) => {
      if (item.zIndex > selectNodeZIndex && item.zIndex <= topMinZIndex) {
        topMinZIndex = item.zIndex;
        return true;
      }
      return false;
    });
    //上边的处理仍然包含不等于topMinZIndex，因此需要再过滤一遍
    topMinNodes = topMinNodes.filter((item) => item.zIndex === topMinZIndex);
    if (topMinNodes?.length) {
      topMinNodes.forEach((item) => {
        item.zIndex = selectNodeZIndex;
      });
    }
    cell.zIndex = topMinZIndex;
  });
  graph.stopBatch('moveUp');
};
export const moveDown = function (graph) {
  let selectCells = graph.getSelectedCells();
  graph.startBatch('moveDown');
  selectCells.forEach((cell) => {
    let bottomMaxZIndex = cell.model.getMinZIndex();
    let selectNodeZIndex = cell.zIndex;
    let topMinNodes = cell.model.getCells().filter((item) => {
      if (item.zIndex < selectNodeZIndex && item.zIndex >= bottomMaxZIndex) {
        bottomMaxZIndex = item.zIndex;
        return true;
      }
      return false;
    });
    //上边的处理仍然包含不等于topMinZIndex，因此需要再过滤一遍
    topMinNodes = topMinNodes.filter((item) => item.zIndex === bottomMaxZIndex);
    if (topMinNodes?.length) {
      topMinNodes.forEach((item) => {
        item.zIndex = selectNodeZIndex;
      });
    }
    cell.zIndex = bottomMaxZIndex;
  });
  graph.stopBatch('moveDown');
};
//自由模式
export const freeModel = function (graph, isUse) {
  if (isUse) {
    //启用自由模式
    graph.disableSnapline();
    graph.setGridSize(0.1);
  } else {
    //禁用自由模式
    graph.enableSnapline();
    graph.setGridSize(10);
  }
};
const SVG_NS = 'http://www.w3.org/2000/svg';
const XLINK_NS = 'http://www.w3.org/1999/xlink';
const spriteDocCache = new Map();

function resolveResourceUrl(url) {
  if (!url) {
    return '';
  }
  if (/^(data:|https?:|blob:)/i.test(url)) {
    return url;
  }
  try {
    return new URL(url, window.location.origin).href;
  } catch {
    return url;
  }
}

function getImageHref(img) {
  return (
    img.getAttribute('href') ||
    img.getAttribute('xlink:href') ||
    img.getAttributeNS(XLINK_NS, 'href')
  );
}

function getUseHref(useEl) {
  return (
    useEl.getAttribute('href') ||
    useEl.getAttribute('xlink:href') ||
    useEl.getAttributeNS(XLINK_NS, 'href')
  );
}

function parseSpriteHref(href) {
  if (!href) {
    return { url: '', id: '' };
  }
  const hashIndex = href.indexOf('#');
  if (hashIndex < 0) {
    return { url: resolveResourceUrl(href), id: '' };
  }
  const urlPart = href.slice(0, hashIndex);
  return {
    url: resolveResourceUrl(urlPart),
    id: href.slice(hashIndex + 1)
  };
}

function imageToDataUriAsync(url) {
  const resolved = resolveResourceUrl(url);
  if (!resolved) {
    return Promise.resolve(null);
  }
  if (resolved.startsWith('data:')) {
    return Promise.resolve(resolved);
  }
  return new Promise((resolve) => {
    DataUri.imageToDataUri(resolved, (err, dataUri) => {
      resolve(!err && dataUri ? dataUri : null);
    });
  });
}

async function loadSpriteDocument(url) {
  if (!url) {
    return null;
  }
  if (spriteDocCache.has(url)) {
    return spriteDocCache.get(url);
  }
  try {
    const res = await fetch(url);
    if (!res.ok) {
      return null;
    }
    const text = await res.text();
    const doc = new DOMParser().parseFromString(text, 'image/svg+xml');
    spriteDocCache.set(url, doc);
    return doc;
  } catch {
    return null;
  }
}

async function prepareExportMarkup(element) {
  const images = [...element.querySelectorAll('image')];
  const uses = [...element.querySelectorAll('use')];
  const spriteSymbols = new Map();

  await Promise.all(
    images.map(async (img) => {
      const dataUri = await imageToDataUriAsync(getImageHref(img));
      if (dataUri) {
        img.setAttribute('data-export-uri', dataUri);
      }
    })
  );

  for (const useEl of uses) {
    const { url, id } = parseSpriteHref(getUseHref(useEl));
    if (!url || !id) {
      continue;
    }
    const exportId = `export-sprite-${id}`;
    if (!spriteSymbols.has(exportId)) {
      const doc = await loadSpriteDocument(url);
      const symbol =
        doc?.getElementById(id) || doc?.querySelector(`[id="${id}"]`);
      if (symbol) {
        const clone = symbol.cloneNode(true);
        clone.setAttribute('id', exportId);
        spriteSymbols.set(exportId, clone);
      }
    }
    if (spriteSymbols.has(exportId)) {
      useEl.setAttribute('data-export-href', `#${exportId}`);
    }
  }

  return { spriteSymbols };
}

function clearExportMarkup(element) {
  element.querySelectorAll('[data-export-uri]').forEach((el) => {
    el.removeAttribute('data-export-uri');
  });
  element.querySelectorAll('[data-export-href]').forEach((el) => {
    el.removeAttribute('data-export-href');
  });
}

function applyImageDataUris(root) {
  root.querySelectorAll('image').forEach((img) => {
    const dataUri = img.getAttribute('data-export-uri');
    if (!dataUri) {
      return;
    }
    if (img.hasAttribute('xlink:href')) {
      img.setAttributeNS(XLINK_NS, 'xlink:href', dataUri);
    }
    img.setAttribute('href', dataUri);
    img.removeAttribute('data-export-uri');
  });
}

function applyUseSpriteHrefs(root) {
  root.querySelectorAll('use').forEach((useEl) => {
    const href = useEl.getAttribute('data-export-href');
    if (!href) {
      return;
    }
    useEl.setAttribute('href', href);
    useEl.setAttributeNS(XLINK_NS, 'xlink:href', href);
    useEl.removeAttribute('data-export-href');
  });
}

function injectSpriteDefs(svgRoot, spriteSymbols) {
  if (!svgRoot || !spriteSymbols.size) {
    return;
  }
  let defs = svgRoot.querySelector('defs');
  if (!defs) {
    defs = document.createElementNS(SVG_NS, 'defs');
    svgRoot.insertBefore(defs, svgRoot.firstChild);
  }
  spriteSymbols.forEach((node) => {
    if (!defs.querySelector(`#${CSS.escape(node.id)}`)) {
      defs.appendChild(node.cloneNode(true));
    }
  });
}

function removeExportChrome(cloneRoot) {
  cloneRoot
    .querySelectorAll(
      '.x6-graph-grid, .x6-widget-selection, .x6-widget-transform'
    )
    .forEach((el) => el.remove());
}

function prepareGraphForExport(graph) {
  if (!graph) {
    return;
  }
  graph.cleanSelection?.();
  graph.clearTransformWidgets?.();
}

function captureCanvasDataUri(canvas) {
  if (!canvas || canvas.width === 0 || canvas.height === 0) {
    return null;
  }
  try {
    return canvas.toDataURL('image/png');
  } catch {
    return null;
  }
}

function createSvgImageElement(x, y, width, height, dataUri) {
  const img = document.createElementNS(SVG_NS, 'image');
  img.setAttribute('href', dataUri);
  img.setAttributeNS(XLINK_NS, 'xlink:href', dataUri);
  img.setAttribute('x', String(x));
  img.setAttribute('y', String(y));
  img.setAttribute('width', String(width));
  img.setAttribute('height', String(height));
  return img;
}

/** 从画布上的 ECharts canvas 截图，供 PNG/SVG 导出使用 */
function collectEchartsSnapshots(graph) {
  const snapshots = [];
  if (!graph) {
    return snapshots;
  }
  graph.getNodes().forEach((node) => {
    if (node.getProp(NODE_TYPE_NAME) !== NODE_TYPES.echarts) {
      return;
    }
    if (node.isVisible && node.isVisible() === false) {
      return;
    }
    const view = graph.findViewByCell(node);
    const container = view?.container;
    const canvas = container?.querySelector('canvas');
    const dataUri = captureCanvasDataUri(canvas);
    if (!dataUri) {
      return;
    }
    const bbox = view.getBBox?.() || node.getBBox();
    snapshots.push({ id: node.id, dataUri, bbox });
    if (container) {
      container.setAttribute('data-export-cell-id', node.id);
      container.setAttribute('data-export-echarts-uri', dataUri);
    }
  });
  return snapshots;
}

function clearEchartsExportMarkers(graph) {
  if (!graph) {
    return;
  }
  graph.getNodes().forEach((node) => {
    if (node.getProp(NODE_TYPE_NAME) !== NODE_TYPES.echarts) {
      return;
    }
    const container = graph.findViewByCell(node)?.container;
    container?.removeAttribute('data-export-cell-id');
    container?.removeAttribute('data-export-echarts-uri');
  });
}

function applyEchartsSnapshots(root, snapshots, { svgMode = false } = {}) {
  const svgRoot =
    root.querySelector?.('.x6-graph-svg svg') ||
    (root instanceof SVGSVGElement || root instanceof SVGElement
      ? root
      : root.documentElement);

  snapshots.forEach(({ id, dataUri, bbox }) => {
    const marker = root.querySelector(`[data-export-cell-id="${id}"]`);
    const foreignObject = marker?.closest('foreignObject');

    if (marker && !svgMode) {
      const img = document.createElement('img');
      img.src = dataUri;
      img.style.width = '100%';
      img.style.height = '100%';
      img.style.display = 'block';
      if (foreignObject) {
        foreignObject.innerHTML = '';
        foreignObject.appendChild(img);
      } else {
        marker.innerHTML = '';
        marker.appendChild(img);
      }
      return;
    }

    if (foreignObject && svgMode) {
      const img = createSvgImageElement(
        foreignObject.getAttribute('x') ?? bbox.x,
        foreignObject.getAttribute('y') ?? bbox.y,
        foreignObject.getAttribute('width') ?? bbox.width,
        foreignObject.getAttribute('height') ?? bbox.height,
        dataUri
      );
      foreignObject.parentNode?.replaceChild(img, foreignObject);
      return;
    }

    if (svgRoot && svgMode) {
      svgRoot.appendChild(
        createSvgImageElement(bbox.x, bbox.y, bbox.width, bbox.height, dataUri)
      );
    } else if (svgRoot && !svgMode) {
      svgRoot.appendChild(
        createSvgImageElement(bbox.x, bbox.y, bbox.width, bbox.height, dataUri)
      );
    }
  });
}

async function inlineSvgExportResources(svgRoot) {
  const images = [...svgRoot.querySelectorAll('image')];
  await Promise.all(
    images.map(async (img) => {
      const dataUri = await imageToDataUriAsync(getImageHref(img));
      if (!dataUri) {
        return;
      }
      img.setAttribute('href', dataUri);
      img.setAttributeNS(XLINK_NS, 'xlink:href', dataUri);
    })
  );

  const uses = [...svgRoot.querySelectorAll('use')];
  const spriteSymbols = new Map();
  for (const useEl of uses) {
    const { url, id } = parseSpriteHref(getUseHref(useEl));
    if (!url || !id) {
      continue;
    }
    const exportId = `export-sprite-${id}`;
    if (!spriteSymbols.has(exportId)) {
      const doc = await loadSpriteDocument(url);
      const symbol =
        doc?.getElementById(id) || doc?.querySelector(`[id="${id}"]`);
      if (symbol) {
        const clone = symbol.cloneNode(true);
        clone.setAttribute('id', exportId);
        spriteSymbols.set(exportId, clone);
      }
    }
    if (spriteSymbols.has(exportId)) {
      useEl.setAttribute('href', `#${exportId}`);
      useEl.setAttributeNS(XLINK_NS, 'xlink:href', `#${exportId}`);
    }
  }
  injectSpriteDefs(svgRoot, spriteSymbols);
}

function downloadSvgString(svgString, fileName = 'chart.svg') {
  DataUri.downloadDataUri(DataUri.svgToDataUrl(svgString), fileName);
}

/** 去掉导出 SVG 中 viewport 的缩放/平移，避免与编辑器 zoom 不一致 */
function resetSvgViewportTransform(svgRoot) {
  if (!svgRoot) {
    return;
  }
  svgRoot
    .querySelectorAll('.x6-graph-svg-viewport, [class*="graph-svg-viewport"]')
    .forEach((el) => {
      el.removeAttribute('transform');
    });
}

export const toPNG = async function (element, callback, option = {}) {
  if (!element) {
    return;
  }
  prepareGraphForExport(option.graph);
  const echartsSnapshots = collectEchartsSnapshots(option.graph);
  const { spriteSymbols } = await prepareExportMarkup(element);
  try {
    const canvas = await html2canvas(element, {
      backgroundColor: null,
      onclone: (_doc, cloneRoot) => {
        const svgRoot =
          cloneRoot.querySelector('.x6-graph-svg svg') ||
          cloneRoot.querySelector('svg');
        injectSpriteDefs(svgRoot, spriteSymbols);
        applyImageDataUris(cloneRoot);
        applyUseSpriteHrefs(cloneRoot);
        applyEchartsSnapshots(cloneRoot, echartsSnapshots);
        removeExportChrome(cloneRoot);

        cloneRoot.querySelectorAll('canvas').forEach((canvasEl) => {
          const width = canvasEl.offsetWidth;
          const height = canvasEl.offsetHeight;
          const imgNode = document.createElement('img');
          imgNode.setAttribute('width', width);
          imgNode.setAttribute('height', height);
          imgNode.setAttribute('src', canvasEl.toDataURL());
          canvasEl.insertAdjacentElement('afterend', imgNode);
          canvasEl.remove();
        });

        if (option.backgroundColor && !option.backgroundImg) {
          const graphSvg = cloneRoot.querySelector('.x6-graph-svg');
          if (graphSvg) {
            graphSvg.style.backgroundColor = option.backgroundColor;
          }
          cloneRoot.style.backgroundColor = option.backgroundColor;
        }
      }
    });
    callback?.(canvas);
  } finally {
    clearExportMarkup(element);
    clearEchartsExportMarkers(option.graph);
  }
};

export const exportPNG = function (element, option = {}) {
  toPNG(
    element,
    (canvas) => {
      canvas.toBlob(function (blob) {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'screenshot.png';
        a.click();
        URL.revokeObjectURL(a.href);
      }, 'image/png');
    },
    option
  );
};

/**
 * 使用 graph.toSVG 导出，并在回调中将外链图片与电力 use 图元内联后下载。
 */
export const exportSVG = function (graph, option = {}) {
  if (!graph?.toSVG) {
    return;
  }
  prepareGraphForExport(graph);
  const echartsSnapshots = collectEchartsSnapshots(graph);
  const { fileName = 'chart.svg', backgroundColor, backgroundImg, toSvgOptions } =
    option;

  graph.toSVG(
    async (svgString) => {
      try {
        const doc = new DOMParser().parseFromString(svgString, 'image/svg+xml');
        const svgRoot = doc.documentElement;
        resetSvgViewportTransform(svgRoot);
        await inlineSvgExportResources(svgRoot);
        applyEchartsSnapshots(svgRoot, echartsSnapshots, { svgMode: true });
        if (echartsSnapshots.length) {
          svgRoot
            .querySelectorAll('foreignObject')
            .forEach((fo) => fo.remove());
        }
        if (backgroundColor && !backgroundImg) {
          const prev = svgRoot.getAttribute('style') || '';
          svgRoot.setAttribute(
            'style',
            `${prev};background-color:${backgroundColor}`
          );
        }
        const out = new XMLSerializer()
          .serializeToString(doc)
          .replace(/&nbsp;/g, '\u00a0');
        downloadSvgString(out, fileName);
      } catch (err) {
        console.error('export SVG failed', err);
      } finally {
        clearEchartsExportMarkers(graph);
      }
    },
    {
      serializeImages: false,
      preserveDimensions: true,
      ...toSvgOptions
    }
  );
};
