export default class Text {
  execute(cellConfig, caseObj, result) {
    let selector = caseObj.touchOff.text.selector;
    let texts = caseObj.touchOff.text.texts;
    if (selector != undefined && selector != '') {
      let returnValue = texts?.find((item) => item.value == result);
      returnValue = returnValue?.text ?? result;
      cellConfig.cell.attr(`${selector}/text`, returnValue);
    }
  }
}
