class Data {
  execute(cellConfig) {
    let format = cellConfig.format;
    if (!format || !format.selector) {
      return;
    }
    if (!format) {
      return;
    }
    let data = cellConfig.data;
    let pointId = `${format.point.mpId}.${format.point.attrId}`;
    for (let [key, value] of Object.entries(data)) {
      if (key === pointId) {
        let returnValue = value.value;
        if (format.multiplier != undefined) {
          returnValue = this.multiplier(format.multiplier, returnValue);
        }
        if (format.decimalNum != undefined) {
          returnValue = this.decimalNum(format.decimalNum, returnValue);
        }
        if (format.unit != undefined && format.unit != '') {
          returnValue += ' ' + format.unit;
        }
        cellConfig.cell.attr(`${format.selector}/text`, returnValue);
        break;
      }
    }
  }
  //放大倍数
  multiplier(multiplier, value) {
    if (isNaN(value)) {
      return value;
    }
    return value * multiplier;
  }
  //保留小数点
  decimalNum(decimalNum, value) {
    if (isNaN(value)) {
      return value;
    }
    return value.toFixed(decimalNum);
  }
}
export default Data;
