function getEdgePoints(cell) {
  const vertices = cell.getVertices();
  const sourcePoint = cell.getSourcePoint();
  const targetPoint = cell.getTargetPoint();
  return [...vertices, sourcePoint, targetPoint];
}

export function getEdgeBBox(cell) {
  const points = getEdgePoints(cell);
  if (!points.length) {
    return { x: 0, y: 0, width: 0, height: 0, centerX: 0, centerY: 0 };
  }
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  points.forEach(({ x, y }) => {
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  });
  return {
    x: minX,
    y: minY,
    width: maxX - minX,
    height: maxY - minY,
    centerX: (minX + maxX) / 2,
    centerY: (minY + maxY) / 2,
    right: maxX,
    bottom: maxY
  };
}

export function translateFreeEdge(cell, dx, dy) {
  if (!dx && !dy) {
    return;
  }
  const vertices = cell.getVertices();
  vertices?.forEach(({ x, y }, index) => {
    cell.setVertexAt(index, { x: x + dx, y: y + dy });
  });
  if (!cell.getSourceCellId()) {
    const { x, y } = cell.getSourcePoint();
    cell.setSource({ x: x + dx, y: y + dy });
  }
  if (!cell.getTargetCellId()) {
    const { x, y } = cell.getTargetPoint();
    cell.setTarget({ x: x + dx, y: y + dy });
  }
}

function sortEdgesByX(edges) {
  return [...edges].sort(
    (a, b) => getEdgeBBox(a).x - getEdgeBBox(b).x
  );
}

function sortEdgesByY(edges) {
  return [...edges].sort(
    (a, b) => getEdgeBBox(a).y - getEdgeBBox(b).y
  );
}

export function edgeLeftAlign(edges) {
  let minX;
  edges.forEach((cell) => {
    const { x } = getEdgeBBox(cell);
    minX = minX ?? x;
    if (x < minX) {
      minX = x;
    }
  });
  edges.forEach((cell) => {
    const { x } = getEdgeBBox(cell);
    translateFreeEdge(cell, minX - x, 0);
  });
}

export function edgeRightAlign(edges) {
  let maxRight;
  edges.forEach((cell) => {
    const { right } = getEdgeBBox(cell);
    maxRight = maxRight ?? right;
    if (right > maxRight) {
      maxRight = right;
    }
  });
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    translateFreeEdge(cell, maxRight - bbox.right, 0);
  });
}

export function edgeTopAlign(edges) {
  let minY;
  edges.forEach((cell) => {
    const { y } = getEdgeBBox(cell);
    minY = minY ?? y;
    if (y < minY) {
      minY = y;
    }
  });
  edges.forEach((cell) => {
    const { y } = getEdgeBBox(cell);
    translateFreeEdge(cell, 0, minY - y);
  });
}

export function edgeBottomAlign(edges) {
  let maxBottom;
  edges.forEach((cell) => {
    const { bottom } = getEdgeBBox(cell);
    maxBottom = maxBottom ?? bottom;
    if (bottom > maxBottom) {
      maxBottom = bottom;
    }
  });
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    translateFreeEdge(cell, 0, maxBottom - bbox.bottom);
  });
}

export function edgeCenterAlign(edges) {
  let minX;
  let maxRight;
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    minX = minX ?? bbox.x;
    maxRight = maxRight ?? bbox.right;
    if (bbox.x < minX) {
      minX = bbox.x;
    }
    if (bbox.right > maxRight) {
      maxRight = bbox.right;
    }
  });
  const center = maxRight - (maxRight - minX) / 2;
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    translateFreeEdge(cell, center - bbox.centerX, 0);
  });
}

export function edgeVerticalCenterAlign(edges) {
  let minY;
  let maxBottom;
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    minY = minY ?? bbox.y;
    maxBottom = maxBottom ?? bbox.bottom;
    if (bbox.y < minY) {
      minY = bbox.y;
    }
    if (bbox.bottom > maxBottom) {
      maxBottom = bbox.bottom;
    }
  });
  const center = maxBottom - (maxBottom - minY) / 2;
  edges.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    translateFreeEdge(cell, 0, center - bbox.centerY);
  });
}

export function edgeHjAlign(edges) {
  const sorted = sortEdgesByX(edges);
  let preRight;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    if (preRight != null) {
      translateFreeEdge(cell, preRight - bbox.x, 0);
    }
    const next = getEdgeBBox(cell);
    preRight = next.right;
  });
}

export function edgePvAlign(edges) {
  const sorted = sortEdgesByY(edges);
  let preBottom;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    if (preBottom != null) {
      translateFreeEdge(cell, 0, preBottom - bbox.y);
    }
    const next = getEdgeBBox(cell);
    preBottom = next.bottom;
  });
}

export function edgeHjAverageAlign(edges) {
  const sorted = sortEdgesByX(edges);
  if (sorted.length < 2) {
    return;
  }
  let minX;
  let maxRight;
  let sumWidth = 0;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    minX = minX ?? bbox.x;
    maxRight = maxRight ?? bbox.right;
    if (bbox.x < minX) {
      minX = bbox.x;
    }
    if (bbox.right > maxRight) {
      maxRight = bbox.right;
    }
    sumWidth += bbox.width;
  });
  const span = maxRight - minX;
  const blank = span - sumWidth;
  if (blank <= 0) {
    return;
  }
  const gap = blank / (sorted.length - 1);
  let preRight;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    if (preRight == null) {
      preRight = bbox.right;
      return;
    }
    const targetX = preRight + gap;
    translateFreeEdge(cell, targetX - bbox.x, 0);
    preRight = getEdgeBBox(cell).right;
  });
}

export function edgePvAverageAlign(edges) {
  const sorted = sortEdgesByY(edges);
  if (sorted.length < 2) {
    return;
  }
  let minY;
  let maxBottom;
  let sumHeight = 0;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    minY = minY ?? bbox.y;
    maxBottom = maxBottom ?? bbox.bottom;
    if (bbox.y < minY) {
      minY = bbox.y;
    }
    if (bbox.bottom > maxBottom) {
      maxBottom = bbox.bottom;
    }
    sumHeight += bbox.height;
  });
  const span = maxBottom - minY;
  const blank = span - sumHeight;
  if (blank <= 0) {
    return;
  }
  const gap = blank / (sorted.length - 1);
  let preBottom;
  sorted.forEach((cell) => {
    const bbox = getEdgeBBox(cell);
    if (preBottom == null) {
      preBottom = bbox.bottom;
      return;
    }
    const targetY = preBottom + gap;
    translateFreeEdge(cell, 0, targetY - bbox.y);
    preBottom = getEdgeBBox(cell).bottom;
  });
}
