import { changeSelectCells } from '../util/Utils';
import { createSelectionSyncController } from '../util/SelectionSyncUtil';
import { AUTO_SELECT_ON_ADDED_FLAG } from '../constants/Constants';

export default class NodeEventHook {
  constructor() {
    this.addedHook = [];
    this.removedHook = [];
    this.selectionChangedHooks = [];
    this.nodeChangeHook = [];
    this.graphInitHook = [];
    this.select = {};
    this.selectionSync = null;
  }
  setGraph(graph) {
    this.disposeSelectionSync();
    this.graph = graph;
    this.graphInitHook.forEach((hook) => hook(graph));
    this.selectionSync = createSelectionSyncController(graph);
    this.selectionSync.onSync((cells, graph) => {
      this.select = cells.length === 1 ? { cell: cells[0] } : {};
      this.selectionChangedHooks.forEach((hook) => hook(cells, graph));
    });
    this.selectionSync.bind();

    graph.on('cell:added', (attr) => {
      const { cell } = attr;
      const data = cell?.getData?.() ?? cell?.store?.data?.data ?? {};
      if (data && data[AUTO_SELECT_ON_ADDED_FLAG] === true) {
        const { [AUTO_SELECT_ON_ADDED_FLAG]: _flag, ...rest } = data;
        if (cell?.setData) {
          cell.setData(rest);
        } else if (cell?.store?.data) {
          cell.store.data.data = rest;
        }
        changeSelectCells(graph, [cell]);
      }
      this.addedHook.forEach((hook) => hook(attr, graph));
    });
    graph.on('cell:removed', (attr) => {
      this.removedHook.forEach((hook) => hook(attr, graph));
    });
    graph.on('node:change:*', (attr) => {
      this.nodeChangeHook.forEach((hook) => hook(attr, graph));
    });
  }
  disposeSelectionSync() {
    if (this.selectionSync) {
      this.selectionSync.dispose();
      this.selectionSync = null;
    }
  }
  getGraph() {
    return this.graph;
  }
  getSelect() {
    return this.select;
  }
  onAdded(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.addedHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.addedHook.push(hook);
    }
  }
  onRemoved(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.removedHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.removedHook.push(hook);
    }
  }
  /**
   * 选区稳定后统一回调（rAF 合并），用于属性面板、工具栏等批量同步
   * @param {(cells: import('@antv/x6').Cell[], graph: import('@antv/x6').Graph) => void} hook
   */
  onSelectionChanged(hook) {
    if (!hook) {
      return;
    }
    const exists = this.selectionChangedHooks.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!exists) {
      this.selectionChangedHooks.push(hook);
    }
  }
  onNodeChange(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.nodeChangeHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.nodeChangeHook.push(hook);
    }
  }
  onGraphInitHook(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.graphInitHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.graphInitHook.push(hook);
    }
  }
  clear() {
    this.disposeSelectionSync();
    this.addedHook = [];
    this.removedHook = [];
    this.selectionChangedHooks = [];
    this.nodeChangeHook = [];
    this.graphInitHook = [];
    this.select = {};
  }
}
