import {
  DEFAULT_GRAPH_FORMAT_VERSION,
  GRAPH_FORMAT_VERSION
} from '../config/SystemConfig.js';

export {
  GRAPH_FORMAT_VERSION,
  DEFAULT_GRAPH_FORMAT_VERSION
} from '../config/SystemConfig.js';

/**
 * 比较两个图纸格式版本号（语义化 x.y）。
 * @returns {-1 | 0 | 1}
 */
export function compareGraphVersion(a, b) {
  const pa = parseVersionParts(a ?? DEFAULT_GRAPH_FORMAT_VERSION);
  const pb = parseVersionParts(b ?? DEFAULT_GRAPH_FORMAT_VERSION);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const na = pa[i] ?? 0;
    const nb = pb[i] ?? 0;
    if (na !== nb) {
      return na < nb ? -1 : 1;
    }
  }
  return 0;
}

function parseVersionParts(version) {
  return String(version)
    .trim()
    .split('.')
    .map((part) => {
      const n = Number(part);
      return Number.isFinite(n) ? n : 0;
    });
}

/** 写入 graph 对象的当前格式版本（保存/导出前调用） */
export function stampGraphConfigVersion(graphConfig) {
  if (!graphConfig || typeof graphConfig !== 'object') {
    return graphConfig;
  }
  graphConfig.version = GRAPH_FORMAT_VERSION;
  return graphConfig;
}
