import { shapeList } from '../config/NodeList.js';
import { imageList } from '../config/ImageList.js';

/** 用户上传图元默认分组 */
export const UPLOAD_GROUP_KEY = 'upload';
/** 装饰图元默认分组 */
export const DECORATE_GROUP_KEY = 'decorate';
/** 图表图元默认分组 */
export const CHARTS_GROUP_KEY = 'charts';
/** 无法识别上传图时的兜底 key */
export const UPLOAD_UNKNOWN_KEY = 'upload::unknown';

/** 与 components/charts 下已注册图表组件名保持同步的兜底列表（registerChart 运行后会追加动态 key） */
const DEFAULT_CHART_SHAPE_KEYS = [
  'BarChart',
  'PieChart',
  'LineChart',
  'CommChart'
];

let registeredChartShapeKeys = [];

const byGroupLabel = new Map();
let registryBuilt = false;

function registryKey(groupKey, label) {
  return `${groupKey}\0${label}`;
}

function registerLabelEntry(groupKey, label, stableKey) {
  if (!groupKey || !label || !stableKey) return;
  byGroupLabel.set(registryKey(groupKey, label), stableKey);
}

function getChartShapeKeysForRegistry() {
  const keys = new Set(DEFAULT_CHART_SHAPE_KEYS);
  registeredChartShapeKeys.forEach((key) => {
    if (key) keys.add(key);
  });
  return [...keys];
}

function buildLabelRegistry() {
  byGroupLabel.clear();

  for (const [groupKey, items] of Object.entries(shapeList)) {
    if (!Array.isArray(items)) continue;
    for (const item of items) {
      const stableKey = getShapeListItemKey(item);
      if (stableKey && item.label) {
        registerLabelEntry(groupKey, item.label, stableKey);
      }
    }
  }

  for (const [groupKey, items] of Object.entries(imageList)) {
    if (!Array.isArray(items)) continue;
    for (const item of items) {
      const stableKey = getImageListItemKey(item);
      if (!stableKey) continue;
      if (item.name) {
        registerLabelEntry(groupKey, item.name, stableKey);
      }
      registerLabelEntry(groupKey, stableKey, stableKey);
    }
  }

  for (const chartKey of getChartShapeKeysForRegistry()) {
    registerLabelEntry(CHARTS_GROUP_KEY, chartKey, chartKey);
  }

  registryBuilt = true;
}

function ensureLabelRegistry() {
  if (!registryBuilt) {
    buildLabelRegistry();
  }
}

/**
 * 图表组件注册完成后调用，将动态注册的 shape 纳入迁移反查表。
 * 由 ChartNodeList.registerChart 在启动时调用一次。
 */
export function registerChartShapeKeys(keys) {
  if (!Array.isArray(keys)) return;
  registeredChartShapeKeys = keys.filter(Boolean);
  buildLabelRegistry();
}

/** 旧版 Stencil 插件生成的 21 位 nanoid definition key */
export function isPluginGeneratedKey(key) {
  return typeof key === 'string' && /^[A-Za-z0-9_-]{21}$/.test(key);
}

/** NodeList 图元：key 在定义中显式配置 */
export function getShapeListItemKey(item) {
  if (!item?.key) return null;
  return item.key;
}

/**
 * ImageList / 图库项：有 key 用 key，否则用 url（电力图等仅配置 url 的场景）
 */
export function getImageListItemKey(item) {
  if (!item) return null;
  const key = item.key ?? item.url;
  return key || null;
}

/** 将稳定 key 写回图库项，供 Stencil 缓存与反查 */
export function assignImageListItemKey(item) {
  const key = getImageListItemKey(item);
  if (key) {
    item.key = key;
  }
  return key;
}

/** 演示环境上传：文件名 + 大小作为稳定 key */
export function buildDemoUploadImageKey(file) {
  if (!file?.name) {
    return UPLOAD_UNKNOWN_KEY;
  }
  return `upload::${file.name}::${file.size ?? 0}`;
}

/** 正式环境上传：key 与资源 url 一致 */
export function buildUploadImageKeyFromUrl(url) {
  return url || UPLOAD_UNKNOWN_KEY;
}

/** 拖入/插入图片节点时的 definition key */
export function resolveInsertImageKey(url, explicitKey) {
  if (explicitKey) {
    return explicitKey;
  }
  if (typeof url === 'string' && url.startsWith('data:')) {
    return UPLOAD_UNKNOWN_KEY;
  }
  return url || UPLOAD_UNKNOWN_KEY;
}

/** 图库列表项规范化 key（与 getImageListItemKey 规则一致） */
export function getGalleryImageKey(item) {
  return getImageListItemKey(item);
}

/** 图表图元：shape 即 definition key */
export function getChartDefinitionKey(shape) {
  if (!shape || isPluginGeneratedKey(shape)) {
    return null;
  }
  return shape;
}

/** 装饰区图片：url 即 definition key */
export function getDecorateImageKey(url) {
  return url || null;
}

export function imageListItemMatchesKey(item, definitionKey) {
  if (!item || definitionKey == null) return false;
  return getImageListItemKey(item) === definitionKey || item.url === definitionKey;
}

export function findImageListItemByDefinitionKey(items, definitionKey) {
  if (!Array.isArray(items) || definitionKey == null) return undefined;
  return items.find((item) => imageListItemMatchesKey(item, definitionKey));
}

function readCellImageHref(attrs) {
  const body = attrs?.body;
  if (!body || typeof body !== 'object') return null;
  const href = body.href ?? body.xlinkHref;
  if (typeof href !== 'string' || !href || href.startsWith('data:')) {
    return null;
  }
  return href;
}

/**
 * 将旧版 nanoid definition key 反查为稳定 key；无法解析时返回 null（保留原 key）。
 */
export function resolveStableDefinitionKey(cell) {
  if (!cell || typeof cell !== 'object') return null;

  ensureLabelRegistry();

  const groupKey = cell.groupKey ?? '';
  const label = cell.label ?? '';
  const shape = cell.shape ?? '';

  if (groupKey === CHARTS_GROUP_KEY) {
    const chartKey = getChartDefinitionKey(shape);
    if (chartKey) return chartKey;
  }

  const href = readCellImageHref(cell.attrs);
  if (href) {
    return href;
  }

  if (groupKey && label) {
    const byLabel = byGroupLabel.get(registryKey(groupKey, label));
    if (byLabel) return byLabel;
  }

  if (groupKey && shape && !isPluginGeneratedKey(shape)) {
    const byShape = byGroupLabel.get(registryKey(groupKey, shape));
    if (byShape) return byShape;
  }

  return null;
}
